//
// ⚠⚠ NOT AN ANCHOR YET — EXTRACTED BUT NEVER VERIFIED ⚠⚠
//
// The agent that extracted these vectors died mid-task on 2026-08-02, right
// before writing the tests that consume them. Nothing here has ever been run
// against this module: no test imports this file, no byte has been compared,
// no teeth check exists. It parses, and that is all that is known.
//
// Treat it as raw material, not evidence. Before it may be called an anchor:
//   1. reconstruct a sample of the expected values BY HAND from the upstream
//      append sequence + flag arithmetic (the full wire hex appears NOWHERE
//      in msgs.rs as a literal -- the tests are parameterised and assemble it
//      at runtime, so a failed grep proves nothing either way);
//   2. wire it into the test aggregator and drive BOTH directions;
//   3. teeth-check with a deliberate encoder mutation, judged by exit code.
//
// Until then ANCHOR-TASKS.tsv must NOT claim BOLT#2 is covered.
//
// Vendored from `lightningdevkit/rust-lightning`'s `lightning/src/ln/msgs.rs`
// test module -- see modules/lnwire/NOTICE for the required MIT/Apache-2.0
// attribution. Do not hand-edit the vector bodies below; regenerate instead
// if the upstream file changes.
//!
//! BOLT#2 channel-management byte-exact wire vectors for all 13 messages
//! this module implements (`open_channel`, `accept_channel`,
//! `funding_created`, `funding_signed`, `channel_ready`, `update_add_htlc`,
//! `update_fulfill_htlc`, `update_fail_htlc`, `commitment_signed`,
//! `revoke_and_ack`, `update_fee`, `shutdown`, `closing_signed`), extracted
//! from rust-lightning's own `encoding_*`/`do_encoding_*` tests around
//! msgs.rs:5098-6258 at the fetched commit (see NOTICE). Every concrete
//! parameter combination each upstream `#[test]` function actually drives
//! is reproduced here, none synthesized -- e.g. `encoding_open_channel()`
//! calls `do_encoding_open_channel` with all 8 `(bool, bool, bool)` tuples,
//! all 8 are vendored below.
//!
//! IMPORTANT -- no message-type prefix: same convention as
//! `bolt7_announcement_update_kat_vectors.zig` -- rust-lightning's
//! `Writeable`/`.encode()` emits only the message's own fields, never
//! BOLT#1's 2-byte `type` field. `bolt2.zig`'s tests prepend this module's
//! own frame type before driving `decode*`, and strip it back off before
//! comparing `serialize*`'s output against `payload_hex`.
//!
//! Several of these tests build `target_value` from a SEQUENCE of
//! conditional hex fragments (`Vec<u8>::from_hex` appends gated on the
//! test's own boolean parameters, or plain `+=` string concatenation for
//! `commitment_signed`) rather than one literal -- so the full assembled
//! hex for a given parameter combination does not appear anywhere in
//! `msgs.rs` as a contiguous literal. Every `payload_hex` below was
//! reconstructed by mechanically replaying that append sequence per
//! combination (never hand-typed), then cross-checked field-by-field
//! against the struct literal's own numeric values (e.g. `funding_satoshis:
//! 1311768467284833366` decodes to the same bytes the reconstruction
//! produced at that offset) -- see the task notes this vendoring was done
//! under for why a literal-string grep is not a valid check here.

pub const OpenChannelVector = struct {
    description: []const u8,
    /// Full expected wire bytes, BOLT#1's 2-byte `type` field NOT included.
    payload_hex: []const u8,
    chain_hash_hex: []const u8,
    temporary_channel_id_hex: []const u8,
    funding_satoshis: u64,
    push_msat: u64,
    dust_limit_satoshis: u64,
    max_htlc_value_in_flight_msat: u64,
    channel_reserve_satoshis: u64,
    htlc_minimum_msat: u64,
    feerate_per_kw: u32,
    to_self_delay: u16,
    max_accepted_htlcs: u16,
    funding_pubkey_hex: []const u8,
    revocation_basepoint_hex: []const u8,
    payment_basepoint_hex: []const u8,
    delayed_payment_basepoint_hex: []const u8,
    htlc_basepoint_hex: []const u8,
    first_per_commitment_point_hex: []const u8,
    channel_flags: u8,
    /// rust-lightning's `shutdown_scriptpubkey` -- this module's
    /// `upfront_shutdown_script` TLV (type 0). `null` when absent.
    upfront_shutdown_script_hex: ?[]const u8,
    /// rust-lightning's `channel_type` -- this module's `channel_type` TLV
    /// (type 1). `null` when absent; always empty bytes when present
    /// (`ChannelTypeFeatures::empty()` -- no vector exercises a non-empty bitmap).
    channel_type_hex: ?[]const u8,
};

